-- =============================================================================
-- 442 — LE CAHIER D'EXERCICES DE TLE (partie 7)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 442 --niveau Tle --matieres histoire-geo-techno,philosophie-techno --suffixe 7 > supabase/contenu/442_exercices_tle_7.sql
--
-- 87 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo-techno.k159  27 exercices · 9 chapitres
--   histoire-geo-techno.k160  27 exercices · 9 chapitres
--   philosophie-techno.k183  33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b84652fa-0cb6-5467-9b29-c4096f276169'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Centres, périphéries et marges","competence":"lire-tableau","situation":"Yanis prépare une fiche de révision sur la mondialisation : il range les territoires selon leur place dans les flux.","documents":[{"id":"tab","type":"tableau","titre":"Trois types de territoires","source":"D’après le cours.","colonnes":["Type","Exemple","Place dans les flux"],"enteteLignes":true,"lignes":[["Centre","New York","Commande et reçoit de très nombreux flux"],["Périphérie intégrée","Chine côtière","Usines et ports tournés vers l’exportation"],["Marge","Sahel","Très peu de ports, d’aéroports et de câbles"]]}],"questions":[{"enonce":"Touche la case qui décrit le territoire le moins connecté aux flux.","aide":"Cherche la ligne du type « Marge ».","type":"zone","document":"tab","multiple":false},{"enonce":"Range chaque territoire dans la bonne catégorie.","aide":"Appuie-toi sur les exemples du tableau : grandes métropoles, régions d’usines, régions isolées.","type":"categories","categories":[{"id":"c0","texte":"Centres"},{"id":"c1","texte":"Périphéries intégrées"},{"id":"c2","texte":"Marges"}],"items":[{"id":"i0","texte":"Mexique du Nord"},{"id":"i1","texte":"Tokyo"},{"id":"i2","texte":"Londres"},{"id":"i3","texte":"Régions enclavées ou en guerre"},{"id":"i4","texte":"Inde des métropoles"},{"id":"i5","texte":"Sahel"}]},{"enonce":"Complète la phrase avec le bon chiffre.","aide":"C’est très peu : ces pays sont des marges.","type":"trous","segments":["Les pays les moins avancés pèsent environ ",0," % du commerce mondial."],"banque":["25","50","10","1"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Une **marge** comme le Sahel a très peu de ports, d’aéroports et de câbles : elle reste à l’écart des flux."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c2","i4":"c1","i5":"c2"}},"explication":"Les grandes **métropoles** (Londres, Tokyo) sont des centres ; le Mexique du Nord et l’Inde des métropoles sont des **périphéries intégrées** ; le Sahel et les régions enclavées ou en guerre sont des **marges**."},{"cle":{"type":"trous","trous":[["1"]]},"affichage":"1","explication":"Les pays les moins avancés ne représentent qu’environ **1 %** du commerce mondial."}]$ex$::jsonb),
  ('b84652fa-0cb6-5467-9b29-c4096f276169'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La jupe de Casablanca","competence":"analyser-document","situation":"Une marque de vêtements imaginaire, Modélia, veut livrer ses boutiques européennes plus vite. Un article raconte sa décision, une carte la situe.","documents":[{"id":"texte","type":"texte","genre":"article","titre":"Modélia rapproche ses usines","auteur":"Article imaginé pour l’exercice, d’après le cours","blocs":["La marque Modélia fabrique ses jupes à Shanghai. Mais les bateaux mettent des semaines à rejoindre l’Europe et les délais de livraison inquiètent ses boutiques.","En 2024, la direction décide de produire une partie de sa collection à Casablanca, au Maroc : le coût du travail y reste bas, l’Europe est toute proche et les ports sont modernes."]},{"id":"carte","type":"carte","titre":"Deux lieux de production et un marché","fond":"monde","cadrage":[-20,15,135,60],"lieux":[{"id":"z1","lieu":"shanghai","symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lon":-7.59,"lat":33.57,"symbole":"lettre","lettre":"B","teinte":"violet"},{"id":"z3","lieu":"paris","symbole":"lettre","lettre":"C","teinte":"violet"}]}],"questions":[{"enonce":"Touche le mot qui dit ce que Modélia veut raccourcir.","aide":"Cherche ce qui inquiète les boutiques dans la première phrase.","type":"zone","document":"texte","multiple":false},{"enonce":"Touche la lettre qui repère la nouvelle usine, à Casablanca.","aide":"Casablanca est sur la côte atlantique du Maroc, au nord-ouest de l’Afrique.","type":"zone","document":"carte","multiple":false},{"enonce":"Comment s’appelle la stratégie de Modélia ?","aide":"Elle rapproche l’usine de ses clients, sans quitter tout à fait l’étranger.","type":"choix","options":[{"id":"a","texte":"La déréglementation : supprimer des règles aériennes"},{"id":"b","texte":"Le protectionnisme : relever les droits de douane"},{"id":"c","texte":"Le nearshoring : rapprocher la production du marché"},{"id":"d","texte":"Le hub : concentrer les vols sur une plateforme"}],"multiple":false},{"enonce":"Complète avec les trois critères de choix des firmes transnationales.","aide":"Un des critères est cité dans le second paragraphe de l’article.","type":"trous","segments":["Une entreprise choisit ses implantations selon le coût du ",0,", la taille du ",1," et la qualité des ",2,"."],"banque":["drapeau","marché","climat","infrastructures","travail"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"Modélia veut réduire les **délais** de livraison : c’est la raison du changement de lieu de production."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Casablanca est repérée par la lettre **B** : tout près de l’Europe, ce qui raccourcit le trajet."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est le **nearshoring** : une entreprise rapproche une partie de sa production de son marché, comme les usines qui partent vers le Maroc ou le Mexique."},{"cle":{"type":"trous","trous":[["travail"],["marche"],["infrastructures"]]},"affichage":"travail · marché · infrastructures","explication":"Les firmes regardent le coût du **travail**, la taille du **marché** et la qualité des **infrastructures** (ports, routes, réseaux)."}]$ex$::jsonb),
  ('b84652fa-0cb6-5467-9b29-c4096f276169'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Qui décide ? États, régions, firmes","competence":"raisonner","situation":"Lina compare les acteurs qui orientent la mondialisation : elle lit un texte, puis trie des décisions selon leur effet sur les échanges.","documents":[{"id":"texte","type":"texte","genre":"article","titre":"Les règles du jeu changent","auteur":"Texte écrit pour l’exercice, d’après le cours","blocs":["Les États peuvent attirer les investisseurs, par des zones franches ou une fiscalité avantageuse, mais aussi fermer leurs frontières : en 2018, puis fortement en 2025, les États-Unis relèvent leurs droits de douane.","Les organisations régionales, comme l’ASEAN ou l’Union européenne, facilitent les échanges entre leurs membres. Les firmes, elles, se relocalisent parfois près de leurs clients."]},{"id":"tab","type":"tableau","titre":"Trois acteurs","source":"D’après le cours.","colonnes":["Acteur","Exemple de décision"],"enteteLignes":true,"lignes":[["États","Zone franche, droits de douane, sanctions"],["Organisations régionales","Libre circulation des marchandises entre membres"],["Firmes transnationales","Choix d’une usine selon le coût du travail"]]}],"questions":[{"enonce":"Classe chaque décision selon son effet sur les échanges.","aide":"Une barrière gêne les échanges ; une facilité les encourage.","type":"categories","categories":[{"id":"c0","texte":"Attire les flux"},{"id":"c1","texte":"Freine les flux"}],"items":[{"id":"i0","texte":"Relever les droits de douane"},{"id":"i1","texte":"Sanctionner un pays (Russie, depuis 2022)"},{"id":"i2","texte":"Offrir une fiscalité avantageuse"},{"id":"i3","texte":"Supprimer les douanes entre membres"},{"id":"i4","texte":"Créer une zone franche"}]},{"enonce":"Touche le mot qui désigne le choix d’une firme de rapprocher sa production de ses clients.","aide":"C’est un verbe de la dernière phrase.","type":"zone","document":"texte","multiple":false},{"enonce":"Touche la case qui décrit ce que font les organisations régionales.","aide":"Cherche la ligne « Organisations régionales ».","type":"zone","document":"tab","multiple":false},{"enonce":"Sur le croquis de la mondialisation, comment représente-t-on les marges ?","aide":"Les marges sont les territoires les moins intégrés : leur couleur est la plus discrète.","type":"choix","options":[{"id":"a","texte":"En couleur intermédiaire, reliés aux pôles par des flèches"},{"id":"b","texte":"En cercles proportionnels à la population de chaque pays"},{"id":"c","texte":"En couleur foncée, comme les pôles, avec des flèches vers eux"},{"id":"d","texte":"En couleur claire, avec des symboles pour les conflits et les sanctions"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"Zone franche, fiscalité avantageuse et suppression des douanes **attirent** les flux ; droits de douane et sanctions les **freinent** : c’est du protectionnisme."},{"cle":{"type":"zone","ids":["m52"]},"explication":"Les firmes se **relocalisent** : elles déplacent une partie de leur production, par exemple vers le Mexique ou le Maroc."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Les organisations régionales (UE, ASEAN, ACEUM) **facilitent les échanges entre leurs membres**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les **marges** (Sahel, Asie centrale, Afrique centrale) sont en couleur claire ; des symboles signalent les barrières, les sanctions et les conflits."}]$ex$::jsonb),
