  ('e0e6c121-19f0-51b1-becd-68ee080e9425'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Endiguement et deux blocs","competence":"analyser-document","situation":"Jules compare les deux camps de la guerre froide : un court texte explique l’endiguement, un tableau oppose les deux blocs.","documents":[{"id":"texte","type":"texte","genre":"source","titre":"Deux camps face à face","auteur":"Texte écrit pour l’exercice, d’après le cours","blocs":["En 1947, les États-Unis adoptent la doctrine Truman : ils s’engagent à aider les pays menacés par le communisme. Cette politique s’appelle l’endiguement.","De son côté, l’URSS répond par la doctrine Jdanov, qui partage le monde en deux camps. Les deux Grands s’affrontent sans jamais se faire la guerre directement."]},{"id":"tab","type":"tableau","titre":"Les deux blocs","source":"D’après le cours.","colonnes":["","Bloc de l’Ouest","Bloc de l’Est"],"enteteLignes":true,"lignes":[["Chef de file","États-Unis","URSS"],["Alliance militaire","OTAN","Pacte de Varsovie"],["Aide économique","Plan Marshall","CAEM"]]}],"questions":[{"enonce":"Touche le mot qui désigne la politique américaine visant à empêcher l’extension du communisme.","aide":"C’est le mot entre crochets du premier paragraphe, après « s’appelle l’ ».","type":"zone","document":"texte","multiple":false},{"enonce":"Touche la case de l’alliance militaire du bloc de l’Est.","aide":"Cherche la ligne « Alliance militaire », colonne du bloc de l’Est.","type":"zone","document":"tab","multiple":false},{"enonce":"L’OTAN est créée en 1949 et le Pacte de Varsovie en 1955. Combien d’années les séparent ?","aide":"Soustrais 1949 à 1955.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi les deux Grands ne se font-ils jamais la guerre directement ?","aide":"Pense à l’arme que les deux possèdent.","type":"choix","options":[{"id":"a","texte":"La menace nucléaire rendrait une guerre directe trop destructrice"},{"id":"b","texte":"L’ONU leur interdit toute action militaire dans le monde"},{"id":"c","texte":"Les deux pays ont signé la paix dès 1945 pour toujours"}