  ('7bae7608-1aca-518b-8afe-f32605c3e9fe'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi Disney choisit la France","competence":"analyser-document","situation":"Un élève lit une note sur le choix du site européen de Disney et la replace sur une frise.","documents":[{"id":"note","type":"texte","genre":"article","titre":"Note de travail","auteur":"Texte écrit pour l’exercice","blocs":["Au milieu des années 1980, Disney cherche un site pour son parc européen et hésite entre la France et l’Espagne. La région parisienne l’emporte : elle est au centre de l’Europe occidentale et Paris est la première destination touristique du monde.","En 1987, l’État signe un accord : il cède des terrains à prix avantageux et prolonge le RER et l’autoroute jusqu’au site."]},{"id":"frise","type":"frise","titre":"Du contrat à l’ouverture","source":"Dates exactes.","debut":1985,"fin":2005,"pas":5,"evenements":[{"id":"z1","date":1987,"nom":"Accord avec l’État"},{"id":"z2","date":1992,"nom":"Ouverture du parc"},{"id":"z3","date":1994,"nom":"Gare TGV"},{"id":"z4","date":2002,"nom":"Second parc"}]}],"questions":[{"enonce":"Touche les deux moyens de transport que l’État s’engage à prolonger jusqu’au site.","aide":"Cherche dans le second paragraphe : un transport sur rails et une route.","type":"zone","document":"note","multiple":true},{"enonce":"Combien d’années séparent l’accord avec l’État de l’ouverture du parc ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Touche l’événement qui relie le site au réseau à grande vitesse européen.","aide":"Cherche le nom d’un train.","type":"zone","document":"frise","multiple":false},{"enonce":"Que contient l’accord de 1987 d’après la note ?","aide":"Relis le second paragraphe de la note.","type":"choix","options":[{"id":"a","texte":"L’État cède des terrains à bon prix et prolonge le RER et l’autoroute"},{"id":"b","texte":"L’État interdit aux visiteurs étrangers d’entrer dans le grand parc"},{"id":"c","texte":"L’État finance seul le parc et en devient le propriétaire unique"},{"id":"d","texte":"Disney renonce à la France et choisit finalement l’Espagne voisine"}],"multiple":false}]}$ex$::jsonb,
