   $ex${"titre":"Le dilemme de Malacca","competence":"analyser-document","situation":"Un élève croise une note imaginée sur la stratégie chinoise et un tableau des grands ports de la région.","documents":[{"id":"note","type":"texte","genre":"article","titre":"Note stratégique","auteur":"Texte écrit pour l’exercice","blocs":["À Pékin, on s’inquiète : en cas de crise, une flotte adverse pourrait fermer le détroit de Malacca, par où passe une grande part du pétrole importé par la Chine. Cette crainte porte un nom : le dilemme de Malacca.","Pour y répondre, la Chine construit des oléoducs à travers la Birmanie et investit dans le port de Gwadar, au Pakistan. Les pays riverains, eux, préfèrent sécuriser le détroit : l’Indonésie, la Malaisie, Singapour et la Thaïlande organisent des patrouilles communes."]},{"id":"ports","type":"tableau","titre":"Trois ports du détroit","source":"Exemples réels.","colonnes":["Port","Pays","Rôle"],"lignes":[["Singapour","Singapour","Grand port de transbordement et de soutage"],["Port Klang","Malaisie","Grand port desservant Kuala Lumpur"],["Tanjung Pelepas","Malaisie","Port de transbordement concurrent de Singapour"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme la crainte chinoise d’un blocage du détroit.","aide":"Cherche le nom de la crainte, juste avant « de Malacca ».","type":"zone","document":"note","multiple":false},{"enonce":"Range chaque mesure dans la stratégie à laquelle elle appartient.","aide":"Éviter le détroit ou le protéger ?","type":"categories","categories":[{"id":"c0","texte":"Contourner le détroit"},{"id":"c1","texte":"Sécuriser le passage"}],"items":[{"id":"i0","texte":"Patrouilles communes contre la piraterie"},{"id":"i1","texte":"Port de Gwadar au Pakistan"},{"id":"i2","texte":"Présence d’une flotte pour la liberté de navigation"},{"id":"i3","texte":"Échange d’informations par un accord régional"},{"id":"i4","texte":"Nouvelles routes de la soie"},{"id":"i5","texte":"Oléoducs à travers la Birmanie"}]},{"enonce":"Combien de pays participent aux patrouilles communes d’après la note ?","aide":"Compte les pays cités dans le second paragraphe.","type":"nombre","unite":"pays"},{"enonce":"Quel port malaisien fait concurrence à Singapour comme port de transbordement ?","aide":"Lis la colonne « Rôle » du tableau.","type":"choix","options":[{"id":"a","texte":"Port Klang (Malaisie)"},{"id":"b","texte":"Tanjung Pelepas"},{"id":"c","texte":"Gwadar (Pakistan)"},{"id":"d","texte":"Kuala Lumpur (capitale)"}],"multiple":false}]}$ex$::jsonb,
