   $ex${"titre":"L’introduction de Léa","competence":"analyser-document","situation":"Léa prépare la dissertation « Peut-on se passer de la technique ? ». Voici son introduction : repère le rôle de chaque phrase.","documents":[{"id":"intro","type":"fiche","modele":"affiche","entete":"L’introduction de Léa","sousTitre":"Texte écrit pour l’exercice","emoji":"📝","teinte":"violet","lignes":[{"texte":"Hier, mon téléphone est tombé en panne et je ne savais plus quoi faire de ma soirée.","id":"z1"},{"texte":"On peut alors se demander : « Peut-on se passer de la technique ? »","id":"z2"},{"texte":"« Se passer » peut vouloir dire vivre sans confort, ou vivre sans aucun outil.","id":"z3"},{"texte":"La technique semble nous aider à vivre, mais elle nous rend aussi dépendants : peut-on la quitter sans perdre en liberté ?","id":"z4"},{"texte":"Nous verrons d’abord qu’elle est utile, puis qu’elle nous rend dépendants, enfin comment rester maîtres de nos outils.","id":"z5"}]}],"questions":[{"enonce":"Touche la phrase qui formule le problème.","aide":"Le problème naît d’une tension : deux réponses semblent vraies à la fois.","type":"zone","document":"intro","multiple":false},{"enonce":"Associe chaque phrase de l’introduction à son rôle.","aide":"Dans l’ordre : une anecdote, le sujet, deux sens, le plan.","type":"association","gauche":[{"id":"g0","texte":"« Hier, mon téléphone est tombé en panne… »"},{"id":"g1","texte":"« On peut alors se demander… »"},{"id":"g2","texte":"« Se passer peut vouloir dire… »"},{"id":"g3","texte":"« Nous verrons d’abord… »"}],"droite":[{"id":"d0","texte":"L’annonce du plan"},{"id":"d1","texte":"Le sujet cité"},{"id":"d2","texte":"L’analyse des termes"},{"id":"d3","texte":"L’accroche"}]},{"enonce":"Complète la règle de la conclusion.","aide":"On répond clairement et on n’ouvre pas de piste supplémentaire.","type":"trous","segments":["Dans la conclusion, on donne une réponse ",0," au problème, sans ajouter d’idée ",1," ."],"banque":["nette","ancienne","nouvelle","vague"]}]}$ex$::jsonb,
