  ('3980df92-e6b6-5bb0-a9b2-4b99247a9bf8'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le plan de Malik","competence":"argumenter","situation":"Malik prépare le sujet « Être libre, est-ce faire tout ce que l’on veut ? ». Son plan a un point faible : trouve-le et corrige-le.","documents":[{"id":"plan","type":"fiche","modele":"affiche","entete":"Le plan de Malik","sousTitre":"Sujet : « Être libre, est-ce faire tout ce que l’on veut ? » — plan écrit pour l’exercice","emoji":"🗂️","teinte":"bleu","lignes":[{"texte":"I. Oui : être libre, c’est ne rencontrer aucun obstacle à ses envies.","id":"z1"},{"texte":"II. Non : céder à toutes ses envies nous rend esclaves de nos désirs.","id":"z2"},{"texte":"III. Pour moi, la liberté est très importante et tout le monde devrait être libre.","id":"z3"}]}],"questions":[{"enonce":"Touche la partie qui ne fait que donner un avis sans l’argumenter.","aide":"Cherche la partie qui n’apporte ni argument ni exemple.","type":"zone","document":"plan","multiple":false},{"enonce":"Associe chaque partie d’un bon plan à son rôle.","aide":"Le plan va de la réponse naturelle à une réponse plus fine.","type":"association","gauche":[{"id":"g0","texte":"Partie I"},{"id":"g1","texte":"Partie II"},{"id":"g2","texte":"Partie III"}],"droite":[{"id":"d0","texte":"Une réponse plus fine qui tient compte des deux"},{"id":"d1","texte":"La réponse la plus naturelle, justifiée"},{"id":"d2","texte":"Ses limites : ce qu’elle oublie"}]},{"enonce":"Par quelle idée remplacer la partie III ?","aide":"La partie III doit dépasser l’opposition entre les deux premières.","type":"choix","options":[{"id":"a","texte":"La liberté n’existe pas, donc il est inutile de poser cette question"},{"id":"b","texte":"Il faut obéir à toutes les règles sans jamais se demander si elles sont justes"},{"id":"c","texte":"Chacun doit faire ce qu’il veut, puisque les deux premières parties le disent"},{"id":"d","texte":"Être libre, c’est choisir en raison, en suivant des règles qu’on reconnaît justes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est la partie **III** : « pour moi… » est une opinion. Une partie doit contenir une idée, un argument et un exemple analysé."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La partie I défend la réponse **naturelle**, la II en montre les **limites**, la III propose une réponse **plus fine** qui tient compte des deux."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il faut une réponse qui tient compte des deux : **choisir en raison, selon des règles reconnues justes**. Les autres options ignorent une des deux parties ou refusent de répondre."}]$ex$::jsonb),
  ('3980df92-e6b6-5bb0-a9b2-4b99247a9bf8'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quatre heures pour une copie","competence":"raisonner","situation":"Sam prépare l’épreuve de quatre heures. Compare son emploi du temps avec le découpage conseillé, puis repère ce qui cloche.","documents":[{"id":"sam","type":"fiche","modele":"horaires","entete":"L’emploi du temps de Sam","sousTitre":"Son projet pour les 4 heures de l’épreuve","emoji":"⏱️","teinte":"violet","lignes":[{"texte":"Lire les trois sujets et choisir","valeur":"0 h 00 – 0 h 10","id":"z1"},{"texte":"Souligner les mots du sujet","valeur":"0 h 10 – 0 h 20","id":"z2"},{"texte":"Rédiger au propre","valeur":"0 h 20 – 3 h 20","id":"z3"},{"texte":"Relire","valeur":"3 h 20 – 4 h 00","id":"z4"}]},{"id":"conseil","type":"fiche","modele":"horaires","entete":"Le découpage conseillé","sousTitre":"Écrit d’après la méthode de la fiche","emoji":"✅","teinte":"bleu","lignes":[{"texte":"Lire les trois sujets et choisir","valeur":"0 h 00 – 0 h 10"},{"texte":"Analyse, problème, plan au brouillon","valeur":"0 h 10 – 1 h 00"},{"texte":"Introduction et conclusion au brouillon","valeur":"1 h 00 – 1 h 20"},{"texte":"Rédaction au propre","valeur":"1 h 20 – 3 h 45"},{"texte":"Relecture","valeur":"3 h 45 – 4 h 00"}]}],"questions":[{"enonce":"Touche l’étape où Sam se lance dans la rédaction sans avoir préparé son plan ni son introduction.","aide":"Quelle étape de Sam vient juste après le simple soulignement des mots ?","type":"zone","document":"sam","multiple":false},{"enonce":"Combien de minutes Sam prévoit-il de MOINS que le découpage conseillé pour analyser le sujet, poser le problème et bâtir le plan ?","aide":"Conseil : de 0 h 10 à 1 h 00. Sam : de 0 h 10 à 0 h 20.","type":"nombre","unite":"min"},{"enonce":"Combien de minutes de relecture Sam prévoit-il en PLUS que le découpage conseillé ?","aide":"Conseil : de 3 h 45 à 4 h 00. Sam : de 3 h 20 à 4 h 00.","type":"nombre","unite":"min"},{"enonce":"Que risque-t-il d’arriver à la copie de Sam ?","aide":"Pense à ce qu’il manque entre les mots soulignés et la rédaction.","type":"choix","options":[{"id":"a","texte":"Une conclusion qui répète chaque argument dans le même ordre"},{"id":"b","texte":"Un sujet traité à côté parce qu’il l’a relu beaucoup trop"},{"id":"c","texte":"Une introduction trop longue à cause du temps de brouillon"},{"id":"d","texte":"Un plan décidé en écrivant, sans problème clair de départ"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est **« Rédiger au propre »** : Sam n’a ni plan ni problème formulé. Il écrira en découvrant son idée au fil de la plume."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 min","explication":"Le conseil réserve **50 minutes** à cette étape, Sam **10** : il en prévoit **40 de moins**."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 min","explication":"Sam relit **40 minutes**, le conseil en prévoit **15** : **25 de plus**. Ce temps serait mieux employé au brouillon."},{"cle":{"type":"choix","ids":["d"]},"explication":"Sans temps d’analyse ni de plan, Sam risque un **plan décidé en écrivant**, sans problème clair. Les autres défauts supposent un brouillon qu’il n’a pas."}]$ex$::jsonb),
  ('de0ad2f1-d3c7-577c-85e5-1e5ee091c57a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un texte en trois temps","competence":"analyser-texte","situation":"Avant d’expliquer un texte, on repère ses connecteurs pour le découper. Lis ce court texte écrit pour l’exercice.","documents":[{"id":"jade","type":"texte","genre":"article","titre":"Un texte court","blocs":["On dit souvent que tout travail doit rapporter de l’argent. Mais certaines activités valent pour elles-mêmes : jouer d’un instrument pour soi, par exemple, ne rapporte rien. Donc il faut juger une activité de deux façons : par son profit, et par ce qu’elle apporte à celui qui la pratique."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux connecteurs logiques qui découpent le texte en moments.","aide":"Cherche les petits mots qui marquent une objection, puis une conclusion.","type":"zone","document":"jade","multiple":true},{"enonce":"Remets dans l’ordre les trois moments du texte.","aide":"Suis les connecteurs : l’idée reçue, « mais », « donc ».","type":"ordre","items":[{"id":"a","texte":"On conclut : il y a deux façons de juger une activité"},{"id":"b","texte":"On objecte : certaines activités valent pour elles-mêmes"},{"id":"c","texte":"On rappelle une idée répandue : le travail doit rapporter de l’argent"}]},{"enonce":"Quelle est la thèse du texte ?","aide":"La thèse est ce que l’auteur affirme à la fin, contre l’idée répandue.","type":"choix","options":[{"id":"a","texte":"Une activité peut avoir de la valeur sans rien rapporter en argent"},{"id":"b","texte":"Il faut cesser de travailler dès qu’on gagne assez d’argent"},{"id":"c","texte":"Jouer d’un instrument est toujours plus utile que travailler"},{"id":"d","texte":"Seul le profit permet de juger la valeur d’une activité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m28"]},"explication":"Ce sont **« Mais »** (l’objection) et **« Donc »** (la conclusion). Ils découpent le texte en trois moments."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"Idée répandue, **objection**, **conclusion** : c’est le mouvement du texte."},{"cle":{"type":"choix","ids":["a"]},"explication":"La thèse est qu’une activité peut **valoir sans rapporter**. La dernière option est l’idée répandue que l’auteur conteste."}]$ex$::jsonb),
  ('de0ad2f1-d3c7-577c-85e5-1e5ee091c57a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La Lune et le fromage","competence":"analyser-texte","situation":"Dans ce texte écrit pour l’exercice, l’auteur utilise un exemple. Explique-le en suivant la méthode : citer, reformuler, expliquer.","documents":[{"id":"lune","type":"texte","genre":"article","titre":"Croire n’est pas prouver","blocs":["Beaucoup pensent que croire fortement une chose suffit à la rendre vraie. C’est une erreur. Un enfant peut croire de toutes ses forces que la Lune est un fromage : cela ne change rien à la Lune. Ce n’est donc pas l’intensité de ma croyance qui fait la vérité, mais l’accord de ce que je dis avec la chose. Aussi faut-il toujours se demander : sur quoi puis-je appuyer ce que je tiens pour vrai ?"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui désigne ce que l’enfant croit à tort dans l’exemple.","aide":"Cherche ce à quoi l’enfant compare la Lune.","type":"zone","document":"lune","multiple":false},{"enonce":"À quoi sert l’exemple de l’enfant et de la Lune ?","aide":"Relie l’exemple à la phrase qui le précède.","type":"choix","options":[{"id":"a","texte":"À prouver que les enfants se trompent plus que les adultes"},{"id":"b","texte":"À montrer que la vérité dépend de chaque enfant qui y croit"},{"id":"c","texte":"À décrire le paysage que l’auteur regarde chaque soir"},{"id":"d","texte":"À montrer que croire très fort ne change rien à la réalité"}],"multiple":false},{"enonce":"Range ces phrases de copie : simple paraphrase ou vraie explication ?","aide":"La paraphrase répète ; l’explication dit pourquoi et à quoi cela sert.","type":"categories","categories":[{"id":"c0","texte":"Paraphrase"},{"id":"c1","texte":"Explication"}],"items":[{"id":"i0","texte":"Il vise ceux qui confondent conviction et vérité : le vrai suit la chose."},{"id":"i1","texte":"L’exemple est absurde exprès : la Lune reste la même quoi qu’on croie."},{"id":"i2","texte":"Il dit que l’enfant croit à un fromage, et que cela ne change rien à la Lune."},{"id":"i3","texte":"L’auteur dit que croire fort ne suffit pas à rendre une chose vraie."}]},{"enonce":"Complète la synthèse du bloc B.","aide":"Le bloc B demande : la question, l’idée principale, les moments.","type":"trous","segments":["Le texte répond à une ",0," ; sa ",1," tient en une phrase ; il se découpe en deux ",2," ."],"banque":["date","thèse","question","moments","biographie"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"C’est **« fromage »**. L’exemple est volontairement absurde."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’exemple illustre la thèse : **l’intensité d’une croyance ne fait pas la vérité**. La Lune reste la même, quoi qu’on en croie."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"La **paraphrase** redit le texte ; l’**explication** dit pourquoi l’auteur choisit cet exemple et ce qu’il vise."},{"cle":{"type":"trous","trous":[["question"],["these"],["moments"]]},"affichage":"question · thèse · moments","explication":"Le bloc de synthèse demande la **question**, la **thèse** et les **moments** du texte, pas la biographie de l’auteur."}]$ex$::jsonb),
  ('de0ad2f1-d3c7-577c-85e5-1e5ee091c57a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Option 1, pas à pas","competence":"analyser-texte","situation":"Tu fais l’option 1 de l’épreuve sur un texte adapté de Rousseau. Commence par le bloc B, au brouillon : c’est lui qui éclaire le reste.","documents":[{"id":"force","type":"texte","genre":"source","titre":"La force et le droit","blocs":["Le plus fort n’est jamais assez fort pour rester toujours le maître, à moins de transformer sa force en droit et l’obéissance en devoir. Mais un droit qui disparaît dès que la force disparaît n’est pas un droit. Céder à la force est un acte de nécessité : on y cède parce qu’on ne peut pas faire autrement, non parce qu’on le doit. Donc le mot « droit » n’ajoute rien à la force."],"source":"D’après Rousseau, Du contrat social — texte adapté"},{"id":"consignes","type":"fiche","modele":"affiche","entete":"Les questions posées","sousTitre":"Option 1 — énoncé écrit pour l’exercice","emoji":"❓","teinte":"violet","lignes":[{"texte":"A. Expliquez l’expression « transformer sa force en droit ».","id":"z1"},{"texte":"B. Quelle question l’auteur se pose-t-il ? Quels sont les moments du texte ? Quelle est son idée principale ?","id":"z2"},{"texte":"C. Suffit-il d’être le plus fort pour avoir raison ?","id":"z3"}]}],"questions":[{"enonce":"Touche la consigne qui relève du bloc de synthèse.","aide":"Le bloc B demande la question, les moments et l’idée principale.","type":"zone","document":"consignes","multiple":false},{"enonce":"Touche les deux connecteurs qui permettent de découper le texte.","aide":"Cherche un mot d’objection et un mot de conclusion.","type":"zone","document":"force","multiple":true},{"enonce":"Quelle est la thèse du texte ?","aide":"Cherche la phrase qui reprend « nécessité » et « devoir ».","type":"choix","options":[{"id":"a","texte":"Les lois n’ont aucune utilité dans une société bien organisée"},{"id":"b","texte":"Le plus fort a toujours raison parce qu’il est le plus fort"},{"id":"c","texte":"Le droit est toujours plus puissant que la force en toutes choses"},{"id":"d","texte":"La force seule ne crée aucun droit : y céder n’est pas un devoir"}],"multiple":false},{"enonce":"Tu rédiges le bloc C (commentaire). Que faire, que éviter ?","aide":"Le bloc C demande une réflexion argumentée, pas une biographie.","type":"categories","categories":[{"id":"c0","texte":"À faire"},{"id":"c1","texte":"À éviter"}],"items":[{"id":"i0","texte":"Prendre position et l’appuyer par un exemple"},{"id":"i1","texte":"Répondre en une ligne sans justifier"},{"id":"i2","texte":"Raconter la vie de l’auteur"},{"id":"i3","texte":"Discuter la thèse avec une autre référence"}]},{"enonce":"Remets dans l’ordre la méthode de l’explication.","aide":"On comprend le texte d’ensemble avant d’en détailler un passage.","type":"ordre","items":[{"id":"a","texte":"Trouver la question à laquelle l’auteur répond"},{"id":"b","texte":"Formuler la thèse en une phrase"},{"id":"c","texte":"Lire le texte trois fois"},{"id":"d","texte":"Expliquer chaque passage demandé"},{"id":"e","texte":"Découper le texte en moments grâce aux connecteurs"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est la consigne **B** : question, moments, idée principale. La A demande d’expliquer un passage ; la C, une réflexion personnelle."},{"cle":{"type":"zone","ids":["m26","m67"]},"explication":"**« Mais »** et **« Donc »** découpent le texte : l’idée de départ, l’objection, la conclusion."},{"cle":{"type":"choix","ids":["d"]},"explication":"La thèse : **la force ne fonde aucun droit**, céder à elle est une nécessité, non un devoir. La deuxième option est celle que Rousseau réfute."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Au bloc C, on **prend position en argumentant**, avec un exemple et une autre référence. La biographie et la réponse en une ligne sont des pièges."},{"cle":{"type":"ordre","ids":["c","b","a","e","d"]},"explication":"On lit, on trouve la **thèse** et la **question**, on **découpe**, puis on explique les passages."}]$ex$::jsonb),
  ('aa81d3cb-d210-543d-b4df-bc5963accad6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans l’atelier de Nina","competence":"analyser-document","situation":"Nina visite un atelier d’artisan et une galerie. Regarde ce qu’elle y trouve et distingue objet d’usage et œuvre.","documents":[{"id":"atelier","type":"fiche","modele":"affiche","entete":"Dans l’atelier de Nina","sousTitre":"Liste écrite pour l’exercice","emoji":"🎨","teinte":"violet","lignes":[{"texte":"Un bol en terre pour manger la soupe","id":"z1"},{"texte":"Une statue de pierre faite pour être contemplée","id":"z2"},{"texte":"Un tableau accroché dans un musée depuis trois siècles","id":"z3"},{"texte":"Une chaise de cuisine qui s’use à force de servir","id":"z4"}]}],"questions":[{"enonce":"Touche les deux objets qui sont des œuvres d’art.","aide":"Cherche ce qui est fait pour être contemplé et pour durer.","type":"zone","document":"atelier","multiple":true},{"enonce":"Associe chaque mot à ce qu’il désigne.","aide":"Pense à ce qu’on attend de l’objet produit.","type":"association","gauche":[{"id":"g0","texte":"L’artisan"},{"id":"g1","texte":"L’artiste"},{"id":"g2","texte":"Le latin ars"},{"id":"g3","texte":"Hannah Arendt"}],"droite":[{"id":"d0","texte":"L’œuvre est l’objet le plus durable du monde humain"},{"id":"d1","texte":"Produit un objet d’usage, qui sert puis s’use"},{"id":"d2","texte":"Un savoir-faire réglé, comme le grec technè"},{"id":"d3","texte":"Produit une œuvre, faite pour être contemplée et durer"}]},{"enonce":"Complète la phrase.","aide":"Un grille-pain s’use ; une œuvre, non.","type":"trous","segments":["L’œuvre d’art échappe à la ",0," : c’est pourquoi on la garde des siècles."],"banque":["consommation","contemplation","fabrication","vente"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2","z3"]},"explication":"La **statue** et le **tableau** sont des œuvres : on les contemple et on les garde. Le bol et la chaise servent, puis s’usent."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"L’**artisan** fait servir, l’**artiste** fait contempler ; *ars* est un savoir-faire réglé ; **Arendt** souligne la durée de l’œuvre."},{"cle":{"type":"trous","trous":[["consommation"]]},"affichage":"consommation","explication":"Elle échappe à la **consommation** : on ne la consomme pas, on la contemple."}]$ex$::jsonb),
  ('aa81d3cb-d210-543d-b4df-bc5963accad6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Des goûts et des couleurs","competence":"argumenter","situation":"Lou et Ben sont devant un tableau. Distingue ce qui est simplement agréable de ce qui est beau.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Au musée","participants":[{"nom":"Lou","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lou","texte":"Ce tableau est magnifique !"},{"qui":"Ben","texte":"Pas mon style. Des goûts et des couleurs, on ne discute pas."},{"qui":"Lou","texte":"Si. Quand je dis que c’est beau, j’attends que tu sois d’accord."},{"qui":"Ben","texte":"Tu ne parles donc pas seulement pour toi ?"},{"qui":"Lou","texte":"Non. Et il plaît encore après trois siècles, dans tous les pays."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot du proverbe que Lou conteste.","aide":"Quel verbe Lou refuse-t-elle quand elle dit « Si » ?","type":"zone","document":"sms","multiple":false},{"enonce":"Quelle idée Lou défend-elle quand elle dit « c’est beau » ?","aide":"Elle attend l’accord de Ben.","type":"choix","options":[{"id":"a","texte":"Le beau est ce qui plaît à celui qui possède l’objet"},{"id":"b","texte":"Le beau dépend uniquement du prix de l’œuvre en vente"},{"id":"c","texte":"Le beau et l’agréable sont exactement la même chose"},{"id":"d","texte":"Le beau prétend valoir pour tous, l’agréable seulement pour moi"}],"multiple":false},{"enonce":"Touche le mot qui rappelle le critère de Hume.","aide":"Hume parle de l’épreuve du temps.","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces phrases : agréable ou beau (selon Kant) ?","aide":"L’agréable touche mes sens et mon intérêt ; le beau, non.","type":"categories","categories":[{"id":"c0","texte":"L’agréable"},{"id":"c1","texte":"Le beau"}],"items":[{"id":"i0","texte":"Je veux posséder l’objet et le consommer"},{"id":"i1","texte":"J’attends que les autres soient d’accord avec moi"},{"id":"i2","texte":"Le plaisir est désintéressé"},{"id":"i3","texte":"Je dis « ça me plaît » sans chercher l’accord de personne"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"C’est **« discute »** : Lou pense que le beau se discute, car il prétend valoir pour tous."},{"cle":{"type":"choix","ids":["d"]},"explication":"Lou rejoint Kant : **le beau prétend à l’accord de tous**, alors que l’agréable reste personnel."},{"cle":{"type":"zone","ids":["m46"]},"explication":"C’est **« siècles »** : une œuvre qui plaît encore à des époques et des peuples différents a passé l’épreuve du temps."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"L’**agréable** est personnel et intéressé ; le **beau** est désintéressé et prétend à l’accord de tous."}]$ex$::jsonb),
  ('aa81d3cb-d210-543d-b4df-bc5963accad6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Copier la nature ?","competence":"argumenter","situation":"Trois élèves parlent de peinture, puis tu prépares le sujet « Une œuvre d’art peut-elle être inutile ? ».","documents":[{"id":"eleves","type":"fiche","modele":"affiche","entete":"Trois regards sur la peinture","sousTitre":"Phrases écrites pour l’exercice","emoji":"🖼️","teinte":"bleu","lignes":[{"texte":"A. Le peintre copie un objet qui copie déjà une Idée : son image nous trompe.","id":"z1"},{"texte":"B. Une œuvre naît de l’esprit : elle est plus belle que n’importe quel paysage.","id":"z2"},{"texte":"C. L’artiste me fait voir ce que je ne regardais plus, parce que je ne cherchais que l’utile.","id":"z3"}]}],"questions":[{"enonce":"Touche l’élève dont la position rappelle celle de Platon.","aide":"Platon parle d’une copie de copie.","type":"zone","document":"eleves","multiple":false},{"enonce":"Touche l’élève dont la position rappelle celle de Bergson.","aide":"Bergson : notre regard est utilitaire.","type":"zone","document":"eleves","multiple":false},{"enonce":"Quel auteur est proche de l’élève B ?","aide":"B dit que la beauté de l’art dépasse celle de la nature.","type":"choix","options":[{"id":"a","texte":"Hegel"},{"id":"b","texte":"Bergson"},{"id":"c","texte":"Hume"},{"id":"d","texte":"Platon"}],"multiple":false},{"enonce":"Quelle problématique convient au sujet « Une œuvre d’art peut-elle être inutile ? »","aide":"Une problématique montre la tension du sujet : inutile et pourtant précieux.","type":"choix","options":[{"id":"a","texte":"Les artistes doivent-ils être payés comme les artisans qui fabriquent ?"},{"id":"b","texte":"Les musées sont-ils toujours ouverts à tous les visiteurs du pays ?"},{"id":"c","texte":"Si l’œuvre ne sert à rien, pourquoi la garde-t-on et que nous apporte-t-elle ?"},{"id":"d","texte":"Pourquoi les œuvres d’art coûtent-elles plus cher que les objets utiles ?"}],"multiple":false},{"enonce":"Remets dans l’ordre un plan en trois temps.","aide":"Réponse naturelle, objection, dépassement.","type":"ordre","items":[{"id":"a","texte":"Mais elle n’est pas sans effet : elle nous fait voir ce qu’on ne regardait plus"},{"id":"b","texte":"Oui : l’œuvre n’a pas de fonction d’usage, elle se contemple et dure"},{"id":"c","texte":"Elle est donc précieuse sans être utile, et c’est ce qui la distingue d’un objet d’usage"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est **A** : pour Platon, le peintre copie le lit du menuisier, qui copie l’Idée du lit."},{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est **C** : l’artiste **dévoile** ce que notre regard utilitaire ne voit plus."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est **Hegel** : la beauté artistique, née de l’esprit, est supérieure à la beauté naturelle."},{"cle":{"type":"choix","ids":["c"]},"explication":"La bonne problématique met face à face l’**inutilité** et la **valeur** de l’œuvre. Les autres sujets sont à côté."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"Le plan va de la réponse **naturelle** à l’**objection** puis à une réponse qui les tient ensemble."}]$ex$::jsonb),
  ('c5623dbb-4edd-5d81-865f-97f5bd38eed1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Légal ou légitime ?","competence":"analyser-document","situation":"Deux situations réelles de l’histoire. Dans chacune, demande-toi si la loi de l’époque est juste.","documents":[{"id":"cas","type":"fiche","modele":"affiche","entete":"Deux situations","sousTitre":"Faits simplifiés","emoji":"⚖️","teinte":"violet","lignes":[{"texte":"France, avant 1944 : la loi interdit aux femmes de voter.","id":"z1"},{"texte":"Alabama, 1955 : Rosa Parks refuse de céder sa place dans un bus, ce que la loi lui interdit.","id":"z2"}]}],"questions":[{"enonce":"Touche la situation où c’est la loi elle-même qui est injuste.","aide":"Dans laquelle la loi en vigueur impose quelque chose de contraire à l’égalité ?","type":"zone","document":"cas","multiple":false},{"enonce":"Touche la situation où l’acte est illégal mais légitime.","aide":"Quelqu’un désobéit à une loi au nom de la justice.","type":"zone","document":"cas","multiple":false},{"enonce":"Range ces phrases : on juge selon la loi ou selon la justice ?","aide":"Le légal se lit dans un texte ; le légitime, dans un principe.","type":"categories","categories":[{"id":"c0","texte":"On juge selon la loi (légal)"},{"id":"c1","texte":"On juge selon la justice (légitime)"}],"items":[{"id":"i0","texte":"« C’est autorisé par le code de la route »"},{"id":"i1","texte":"« Le règlement le prévoit, article 4 »"},{"id":"i2","texte":"« C’est contraire à la dignité humaine »"},{"id":"i3","texte":"« Personne ne devrait subir cela »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est la situation **A** : la loi est **légale** mais injuste, puisqu’elle exclut les femmes du vote."},{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est la situation **B** : refuser de céder sa place était **illégal** mais **légitime**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Le **légal** renvoie à un texte en vigueur ; le **légitime** à un principe de justice."}]$ex$::jsonb),
  ('c5623dbb-4edd-5d81-865f-97f5bd38eed1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Partager, rendre, corriger","competence":"raisonner","situation":"Un club distribue des bourses, rembourse un prêt et corrige un règlement. Reconnais la forme de justice à l’œuvre.","documents":[{"id":"bourses","type":"tableau","titre":"Bourses du club : 600 € à partager","colonnes":["Élève","Parts de besoin"],"lignes":[["Zoé",1],["Max",2],["Total",3]],"enteteLignes":true,"source":"Chiffres inventés pour l’exercice"},{"id":"lesbos","type":"texte","genre":"source","titre":"La règle de plomb","blocs":["À Lesbos, les maçons mesurent avec une règle de plomb, souple, qui épouse la forme de chaque pierre : elle ne reste pas raide comme une règle de bois. De même, la loi est générale et ne peut tout prévoir ; le juge équitable la corrige quand son application stricte serait injuste."],"source":"D’après Aristote, Éthique à Nicomaque — texte adapté"}],"questions":[{"enonce":"Associe chaque situation à la justice qu’elle illustre.","aide":"Échange exact, partage proportionnel, correction de la loi.","type":"association","gauche":[{"id":"g0","texte":"Lina rend exactement les 12 € que Tom lui avait prêtés"},{"id":"g1","texte":"Le club partage 600 € selon les besoins de chacun"},{"id":"g2","texte":"Un juge adapte un règlement à un cas imprévu"}],"droite":[{"id":"d0","texte":"Justice distributive"},{"id":"d1","texte":"Justice corrective"},{"id":"d2","texte":"Équité"}]},{"enonce":"Le club partage les 600 € en proportion des besoins. Combien reçoit Zoé ?","aide":"Une part vaut 600 ÷ 3.","type":"nombre","unite":"€"},{"enonce":"Touche le mot qui montre que la règle de plomb s’adapte à la pierre.","aide":"Quel verbe dit que la règle suit la forme de la pierre ?","type":"zone","document":"lesbos","multiple":false},{"enonce":"À quoi sert l’image de la règle de plomb ?","aide":"La règle de bois est raide ; celle de plomb suit la pierre.","type":"choix","options":[{"id":"a","texte":"À montrer que les maçons sont plus justes que les juges"},{"id":"b","texte":"À montrer que l’équité adapte la loi au cas particulier"},{"id":"c","texte":"À prouver que la loi doit rester raide et jamais changer"},{"id":"d","texte":"À expliquer comment mesurer précisément les pierres de Lesbos"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Rendre exactement relève de la justice **corrective**, partager selon le besoin de la **distributive**, adapter la loi de l’**équité**."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 €","explication":"Il y a 3 parts : une part vaut 600 ÷ 3 = 200 €. Zoé en a une : **200 €** (Max en reçoit 400). C’est une égalité **proportionnelle**."},{"cle":{"type":"zone","ids":["m12"]},"explication":"C’est **« épouse »** : la règle prend la forme de la pierre, comme le juge équitable adapte la loi au cas."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’image montre que l’**équité** corrige la généralité de la loi là où elle serait injuste."}]$ex$::jsonb),
  ('c5623dbb-4edd-5d81-865f-97f5bd38eed1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La force fait-elle le droit ?","competence":"argumenter","situation":"Inès et Hugo discutent de justice. Retrouve les auteurs derrière leurs phrases, puis teste une société avec Rawls.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Sur le chemin du lycée","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Inès","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"Si personne ne me voit, je ne vois pas pourquoi je serais juste."},{"qui":"Inès","texte":"Même invisible, l’injuste est désordonné en lui-même."},{"qui":"Hugo","texte":"Mais le plus fort fait les lois, alors à quoi bon ?"},{"qui":"Inès","texte":"Céder à la force, c’est une nécessité, pas un devoir."}],"source":"Dialogue écrit pour l’exercice"},{"id":"societes","type":"tableau","titre":"Trois sociétés : revenu annuel moyen de chaque groupe","colonnes":["Société","Plus défavorisés","Classes moyennes","Plus favorisés"],"lignes":[["A",10,40,100],["B",30,50,90],["C",20,20,20]],"enteteLignes":true,"source":"En milliers d’euros, chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui renvoie à l’anneau de Gygès.","aide":"Quel mot évoque l’anneau qui rend invisible ?","type":"zone","document":"sms","multiple":false},{"enonce":"Touche le mot qui renvoie à Rousseau.","aide":"Rousseau : céder à la force est un acte de …","type":"zone","document":"sms","multiple":false},{"enonce":"Associe chaque auteur à son idée.","aide":"Pense à Gygès, au constat amer, à la nécessité, au voile.","type":"association","gauche":[{"id":"g0","texte":"Platon"},{"id":"g1","texte":"Pascal"},{"id":"g2","texte":"Rousseau"},{"id":"g3","texte":"Rawls"}],"droite":[{"id":"d0","texte":"L’injuste est désordonné en lui-même, jamais vraiment heureux"},{"id":"d1","texte":"Céder à la force est une nécessité, non un devoir"},{"id":"d2","texte":"Faute de rendre le juste fort, on a déclaré juste ce qui est fort"},{"id":"d3","texte":"Choisir les règles sans savoir quelle place on aura"}]},{"enonce":"Derrière le voile d’ignorance, quelle société Rawls jugerait-il la plus juste ?","aide":"Rawls accepte des inégalités si elles profitent aux plus défavorisés.","type":"choix","options":[{"id":"a","texte":"Aucune des trois, car il refuse d’en choisir une"},{"id":"b","texte":"La société A, où les plus favorisés gagnent le plus"},{"id":"c","texte":"La société C, parce qu’elle ne comporte aucune inégalité"},{"id":"d","texte":"La société B, où les plus défavorisés vivent le mieux"}],"multiple":false},{"enonce":"De combien de milliers d’euros les plus défavorisés gagnent-ils davantage dans la société B que dans la société C ?","aide":"Compare les deux cases de la colonne « Plus défavorisés ».","type":"nombre","unite":"k€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"C’est **« invisible »** : le récit de Platon pose la question de la justice sans témoin."},{"cle":{"type":"zone","ids":["m39"]},"explication":"C’est **« nécessité »** : pour Rousseau, céder à la force est une nécessité, non un devoir."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**Platon** : l’injuste est désordonné ; **Pascal** constate que la force a pris le nom de justice ; **Rousseau** : nécessité, non devoir ; **Rawls** : le voile d’ignorance."},{"cle":{"type":"choix","ids":["d"]},"explication":"Dans **B**, les plus défavorisés gagnent 30, contre 10 en A et 20 en C : l’inégalité leur profite. Rawls choisirait **B**."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 k€","explication":"30 − 20 = **10** milliers d’euros : l’inégalité de B profite aux plus défavorisés."}]$ex$::jsonb),
  ('c62489eb-3035-569a-a0a6-0dba9ce32636'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois façons d’être libre","competence":"analyser-document","situation":"Le mot « liberté » pose trois questions différentes. Lis ces trois phrases et reconnais la question de chacune.","documents":[{"id":"phrases","type":"fiche","modele":"affiche","entete":"Trois phrases d’élèves","sousTitre":"Écrites pour l’exercice","emoji":"🕊️","teinte":"violet","lignes":[{"texte":"« Personne ne m’empêche d’aller au cinéma avec mes amis. »","id":"z1"},{"texte":"« Mon choix vient-il vraiment de moi, ou de mon éducation ? »","id":"z2"},{"texte":"« Je n’obéis qu’à des lois que j’ai contribué à voter. »","id":"z3"}]}],"questions":[{"enonce":"Touche la phrase qui pose la question du libre arbitre.","aide":"Cherche celle qui se demande si le choix vient vraiment de moi.","type":"zone","document":"phrases","multiple":false},{"enonce":"Associe chaque phrase au sens de la liberté qu’elle exprime.","aide":"Un obstacle, une cause, des lois.","type":"association","gauche":[{"id":"g0","texte":"Personne ne m’empêche d’aller au cinéma"},{"id":"g1","texte":"Mon choix vient-il vraiment de moi ?"},{"id":"g2","texte":"Je n’obéis qu’aux lois que j’ai votées"}],"droite":[{"id":"d0","texte":"Le libre arbitre"},{"id":"d1","texte":"Faire ce qui me plaît"},{"id":"d2","texte":"La liberté politique"}]},{"enonce":"Range ces situations selon la liberté qui est en cause.","aide":"Obstacle physique, cause du choix, pouvoir politique.","type":"categories","categories":[{"id":"c0","texte":"Faire ce qui me plaît"},{"id":"c1","texte":"Libre arbitre"},{"id":"c2","texte":"Liberté politique"}],"items":[{"id":"i0","texte":"Un bras cassé m’empêche de jouer au basket"},{"id":"i1","texte":"Un tyran interdit toute critique du pouvoir"},{"id":"i2","texte":"Mes gènes et mon éducation décident-ils de tout ?"},{"id":"i3","texte":"Un cadenas m’empêche d’entrer dans le local"},{"id":"i4","texte":"Mes choix sont-ils causés par ce que j’ignore ?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est la phrase **2** : elle demande si le choix vient de soi ou de causes extérieures, c’est la question du **libre arbitre**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Chaque phrase correspond à un sens : **faire ce qui me plaît** (pas d’obstacle), **libre arbitre** (le choix vient de moi ?), **liberté politique** (sous quelles lois ?)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Un **obstacle** touche la liberté de faire ce qu’on veut ; la **cause du choix** touche le libre arbitre ; le **pouvoir** touche la liberté politique."}]$ex$::jsonb),
  ('c62489eb-3035-569a-a0a6-0dba9ce32636'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Ce qui dépend de nous","competence":"raisonner","situation":"Mila joue un match important. Utilise la distinction d’Épictète, puis place quelques auteurs.","documents":[{"id":"mila","type":"fiche","modele":"affiche","entete":"Avant le match de Mila","sousTitre":"Liste écrite pour l’exercice","emoji":"🏐","teinte":"bleu","lignes":[{"texte":"La météo du jour","id":"z1"},{"texte":"La façon dont elle juge son propre jeu","id":"z2"},{"texte":"Son désir de progresser","id":"z3"},{"texte":"L’avis des spectateurs sur son niveau","id":"z4"},{"texte":"L’état de santé de son adversaire","id":"z5"}]}],"questions":[{"enonce":"Touche les deux choses qui dépendent de Mila, selon Épictète.","aide":"Épictète : nos jugements et nos désirs.","type":"zone","document":"mila","multiple":true},{"enonce":"Quel conseil Épictète donnerait-il à Mila après un match raté ?","aide":"Il sépare ce qui dépend de nous de ce qui n’en dépend pas.","type":"choix","options":[{"id":"a","texte":"Se concentrer sur son jugement et ses efforts plutôt que sur l’avis des autres"},{"id":"b","texte":"S’inquiéter surtout de ce que les spectateurs pensent de son niveau"},{"id":"c","texte":"Renoncer à tout désir pour ne plus jamais être déçue du jeu"},{"id":"d","texte":"Attendre que la météo change avant de juger son propre match"}],"multiple":false},{"enonce":"Associe chaque auteur à son idée sur la liberté.","aide":"Pense à l’indifférence, aux causes ignorées, au choix inévitable, à la loi.","type":"association","gauche":[{"id":"g0","texte":"Descartes"},{"id":"g1","texte":"Spinoza"},{"id":"g2","texte":"Sartre"},{"id":"g3","texte":"Rousseau"}],"droite":[{"id":"d0","texte":"On se croit libre par ignorance des causes qui nous déterminent"},{"id":"d1","texte":"Ne pas choisir est encore un choix"},{"id":"d2","texte":"La liberté d’indifférence est le plus bas degré de la liberté"},{"id":"d3","texte":"Obéir à la loi qu’on s’est prescrite, c’est être libre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2","z3"]},"explication":"Ce qui dépend d’elle, c’est **sa façon de juger son jeu** et **son désir de progresser**. La météo, l’avis des autres et la santé de l’adversaire n’en dépendent pas."},{"cle":{"type":"choix","ids":["a"]},"explication":"Épictète conseille de porter son attention sur ce qui **dépend de nous** : ses jugements, ses efforts. Le reste ne se commande pas."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**Descartes** : choisir sans raison est le plus bas degré ; **Spinoza** : on ignore les causes ; **Sartre** : on est condamné à choisir ; **Rousseau** : la loi qu’on s’est donnée libère."}]$ex$::jsonb),
  ('c62489eb-3035-569a-a0a6-0dba9ce32636'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Obéir, est-ce ne plus être libre ?","competence":"argumenter","situation":"Tu prépares le sujet « Être libre, est-ce n’obéir à personne ? » à partir d’un texte adapté de Rousseau.","documents":[{"id":"rousseau","type":"texte","genre":"source","titre":"Le maître de soi","blocs":["Céder à chaque envie, c’est obéir à son appétit et devenir son esclave. Obéir à une loi que l’on s’est donnée soi-même, c’est au contraire être libre. Le citoyen est libre quand il obéit à des lois qu’il a contribué à faire."],"source":"D’après Rousseau, Du contrat social — texte adapté"},{"id":"pistes","type":"fiche","modele":"affiche","entete":"Le plan de la copie","sousTitre":"Plan écrit pour l’exercice","emoji":"🗂️","teinte":"violet","lignes":[{"texte":"Refuser toute obéissance livre au caprice et aux plus forts","id":"z1"},{"texte":"Obéir à une loi juste, reconnue comme sienne, est une liberté supérieure","id":"z2"},{"texte":"Cette liberté exige un effort de jugement personnel","id":"z3"}]}],"questions":[{"enonce":"Touche le mot qui décrit celui qui cède à chacune de ses envies.","aide":"Cherche le mot qui s’oppose à « libre ».","type":"zone","document":"rousseau","multiple":false},{"enonce":"Quelle est la thèse du texte ?","aide":"La thèse se trouve dans la deuxième phrase.","type":"choix","options":[{"id":"a","texte":"Être libre, c’est ne jamais obéir à aucune règle écrite"},{"id":"b","texte":"Obéir à une loi qu’on s’est donnée est une forme de liberté"},{"id":"c","texte":"Céder à ses envies est la meilleure façon d’être libre"},{"id":"d","texte":"Les lois sont toujours l’ennemi de la liberté des citoyens"}],"multiple":false},{"enonce":"Trie ces arguments pour le sujet « Être libre, est-ce n’obéir à personne ? »","aide":"Deux arguments défendent l’indépendance, deux défendent l’obéissance à la loi.","type":"categories","categories":[{"id":"c0","texte":"Oui, être libre c’est n’obéir à personne"},{"id":"c1","texte":"Non, on peut être libre en obéissant"}],"items":[{"id":"i0","texte":"Sans loi, le plus fort peut tout imposer aux autres"},{"id":"i1","texte":"Suivre des ordres sans les comprendre, ce n’est pas choisir"},{"id":"i2","texte":"Obéir à un ordre arbitraire, c’est dépendre de la volonté d’autrui"},{"id":"i3","texte":"Se donner ses propres lois, c’est n’obéir qu’à soi-même"}]},{"enonce":"Remets dans l’ordre les trois parties du plan.","aide":"Du plus naturel vers le plus fin.","type":"ordre","items":[{"id":"a","texte":"Refuser toute obéissance livre au caprice et aux plus forts"},{"id":"b","texte":"Cette liberté exige un effort de jugement personnel"},{"id":"c","texte":"Obéir à une loi juste, reconnue comme sienne, est une liberté supérieure"}]},{"enonce":"Quelle problématique convient au sujet ?","aide":"Elle doit exprimer la tension entre deux réponses qui semblent vraies.","type":"choix","options":[{"id":"a","texte":"Les lois d’un pays sont-elles toutes écrites dans un même grand code ?"},{"id":"b","texte":"Si refuser toute obéissance nous livre aux plus forts, peut-on être libre en obéissant ?"},{"id":"c","texte":"Pourquoi les élèves doivent-ils obéir à leurs professeurs pendant les cours ?"},{"id":"d","texte":"Faut-il punir ceux qui ne respectent jamais les règles de la route ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"C’est **« esclave »** : pour Rousseau, l’impulsion du seul appétit est une servitude."},{"cle":{"type":"choix","ids":["b"]},"explication":"La thèse : **obéir à une loi qu’on s’est donnée soi-même, c’est être libre**. Les autres options renversent le texte."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Les deux premiers défendent le **oui** (dépendre d’autrui), les deux autres le **non** (la loi protège et peut être choisie)."},{"cle":{"type":"ordre","ids":["a","c","b"]},"explication":"Le plan va du **refus de toute obéissance** à l’**obéissance choisie**, puis à l’**effort de jugement**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La bonne problématique oppose **refus d’obéir** et **obéissance choisie** : c’est la tension du sujet."}]$ex$::jsonb),
  ('0c8b9c50-aade-507f-93a1-ee836959e277'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre fois le mot nature","competence":"comprendre-langue","situation":"Le mot « nature » change de sens d’une phrase à l’autre. Repère chaque sens.","documents":[{"id":"usages","type":"fiche","modele":"affiche","entete":"Quatre phrases","sousTitre":"Écrites pour l’exercice","emoji":"🌿","teinte":"violet","lignes":[{"texte":"Nous campons au cœur de la nature, loin de tout village.","id":"z1"},{"texte":"La nature du cercle, c’est d’avoir tous ses points à égale distance du centre.","id":"z2"},{"texte":"Il est dans la nature humaine de vouloir être aimé.","id":"z3"},{"texte":"La graine devient arbre : c’est dans sa nature de grandir toute seule.","id":"z4"}]}],"questions":[{"enonce":"Touche la phrase où « nature » veut dire l’essence d’une chose.","aide":"Cherche la phrase qui dit ce qu’est le cercle.","type":"zone","document":"usages","multiple":false},{"enonce":"Associe chaque phrase au sens de « nature ».","aide":"Quatre sens : ensemble, essence, nature humaine, principe interne.","type":"association","gauche":[{"id":"g0","texte":"Nous campons au cœur de la nature"},{"id":"g1","texte":"La nature du cercle"},{"id":"g2","texte":"La nature humaine"},{"id":"g3","texte":"La graine grandit dans sa nature"}],"droite":[{"id":"d0","texte":"L’essence, ce qu’est la chose"},{"id":"d1","texte":"Un principe interne de développement"},{"id":"d2","texte":"L’ensemble des êtres, sans intervention humaine"},{"id":"d3","texte":"Ce qui serait commun à tous les hommes"}]},{"enonce":"Complète la phrase d’Aristote.","aide":"Le lit ne pousse pas tout seul.","type":"trous","segments":["L’arbre porte en lui-même le principe de son mouvement : c’est ce qui distingue l’être ",0," de l’objet ",1," ."],"banque":["ancien","vivant","technique","naturel"]}]}$ex$::jsonb,
