  ('0c8b9c50-aade-507f-93a1-ee836959e277'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les marais de Marais","competence":"raisonner","situation":"Dans ce récit écrit pour l’exercice, un village transforme la nature. Mesure ce que cela apporte et ce que cela coûte.","documents":[{"id":"village","type":"texte","genre":"recit","titre":"Le village de Marais","blocs":["À Marais, on a asséché les marécages : le paludisme a disparu et les récoltes ont doublé. Mais les oiseaux migrateurs ne viennent plus, et la nappe d’eau baisse chaque année. Les enfants d’aujourd’hui mangent à leur faim ; ceux de demain risquent d’avoir soif."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre un bénéfice pour la santé, celui que Descartes met en premier.","aide":"Quelle maladie a disparu ?","type":"zone","document":"village","multiple":false},{"enonce":"Touche le mot qui montre le danger pour les générations futures.","aide":"Quel mot dit ce qui menace les enfants de demain ?","type":"zone","document":"village","multiple":false},{"enonce":"Quelle idée de Hans Jonas ce récit illustre-t-il ?","aide":"Pense à la responsabilité envers les générations futures.","type":"choix","options":[{"id":"a","texte":"La technique est neutre et ne pose jamais de problème moral"},{"id":"b","texte":"Nos actions engagent désormais l’avenir et il faut en répondre"},{"id":"c","texte":"La nature doit être dominée sans se soucier de ses limites"},{"id":"d","texte":"Il faut retourner vivre sans aucune technique ni outil moderne"}],"multiple":false},{"enonce":"Associe chaque auteur à son idée sur la nature.","aide":"Principe interne, maîtrise, perfectibilité, responsabilité.","type":"association","gauche":[{"id":"g0","texte":"Aristote"},{"id":"g1","texte":"Descartes"},{"id":"g2","texte":"Rousseau"},{"id":"g3","texte":"Hans Jonas"}],"droite":[{"id":"d0","texte":"Devenir comme maîtres et possesseurs de la nature, d’abord pour la santé"},{"id":"d1","texte":"L’être naturel a en lui-même son principe de mouvement"},{"id":"d2","texte":"L’homme se distingue par sa perfectibilité"},{"id":"d3","texte":"Une responsabilité envers les générations futures"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"C’est **« paludisme »** : Descartes attend de la maîtrise de la nature d’abord la santé."},{"cle":{"type":"zone","ids":["m45"]},"explication":"C’est **« soif »** : nos actions engagent l’avenir, c’est le cœur de l’éthique de Jonas."},{"cle":{"type":"choix","ids":["b"]},"explication":"Jonas fonde une éthique de la **responsabilité** : le pouvoir humain engage l’avenir, donc il faut en répondre."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**Aristote** : principe interne ; **Descartes** : maîtrise pour la santé ; **Rousseau** : perfectibilité ; **Jonas** : responsabilité."}]$ex$::jsonb),
  ('0c8b9c50-aade-507f-93a1-ee836959e277'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Y a-t-il une nature humaine ?","competence":"argumenter","situation":"Trois élèves débattent de la nature humaine. Un tableau l’éclaire avec le critère de Lévi-Strauss.","documents":[{"id":"eleves","type":"fiche","modele":"affiche","entete":"Trois élèves","sousTitre":"Phrases écrites pour l’exercice","emoji":"💬","teinte":"bleu","lignes":[{"texte":"Inès : « Marcher, parler, manger sont des besoins naturels, mais chacun les vit à la manière de sa culture. »","id":"z1"},{"texte":"Noah : « Nous n’avons pas de nature fixée d’avance : on se définit par ce qu’on fait. »","id":"z2"},{"texte":"Tess : « L’animal reste ce qu’il est ; nous, nous pouvons nous transformer, en mieux ou en pire. »","id":"z3"}]},{"id":"regles","type":"tableau","titre":"Quatre règles, quatre sociétés","colonnes":["Règle","Présente dans…","Universelle ?"],"lignes":[["Interdire le mariage entre frère et sœur","Toutes les sociétés connues","Oui"],["Se saluer en se serrant la main","Certaines sociétés seulement","Non"],["Manger avec des baguettes","Certaines sociétés seulement","Non"],["Saluer en s’inclinant","Certaines sociétés seulement","Non"]],"enteteLignes":true,"source":"D’après la réflexion de Claude Lévi-Strauss ; tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’élève qui parle comme Sartre.","aide":"Sartre : l’existence précède l’essence.","type":"zone","document":"eleves","multiple":false},{"enonce":"Touche l’élève qui parle comme Merleau-Ponty.","aide":"Merleau-Ponty : tout est fabriqué et tout est naturel.","type":"zone","document":"eleves","multiple":false},{"enonce":"Quel auteur Tess rappelle-t-elle ?","aide":"Elle parle d’une capacité de se transformer.","type":"choix","options":[{"id":"a","texte":"Lévi-Strauss"},{"id":"b","texte":"Rousseau"},{"id":"c","texte":"Aristote"},{"id":"d","texte":"Hans Jonas"}],"multiple":false},{"enonce":"Range ces règles du tableau.","aide":"Regarde la colonne « Universelle ? ».","type":"categories","categories":[{"id":"c0","texte":"Règle propre à certaines sociétés (culture)"},{"id":"c1","texte":"Règle universelle, pourtant une règle"}],"items":[{"id":"i0","texte":"Saluer en s’inclinant"},{"id":"i1","texte":"Se saluer en se serrant la main"},{"id":"i2","texte":"Interdire le mariage entre frère et sœur"},{"id":"i3","texte":"Manger avec des baguettes"}]},{"enonce":"Que conclure du tableau, avec le critère de Lévi-Strauss ?","aide":"Ce qui est universel relève de la nature ; ce qui suit une règle, de la culture.","type":"choix","options":[{"id":"a","texte":"Toutes les règles du tableau relèvent uniquement de la nature humaine"},{"id":"b","texte":"Aucune des règles du tableau ne relève jamais de la culture humaine"},{"id":"c","texte":"Les règles universelles sont toujours biologiques et jamais apprises"},{"id":"d","texte":"L’interdiction de l’inceste est une règle et pourtant universelle, donc à la frontière"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est **Noah** : pour Sartre, il n’y a pas de nature humaine fixée d’avance, on se définit par ce qu’on fait."},{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est **Inès** : les besoins sont naturels, mais toujours façonnés par une culture."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est **Rousseau** : l’homme se distingue de l’animal par sa **perfectibilité**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Une règle **propre à certaines sociétés** relève de la culture ; seule l’interdiction entre frère et sœur est à la fois une **règle** et **universelle**."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’interdiction de l’inceste est une **règle universelle** : elle marque le passage de la **nature à la culture**."}]$ex$::jsonb),
