   $ex${"titre":"Sacré et profane","competence":"analyser-texte","situation":"Lina visite une mosquée avec sa classe. Lis ce récit écrit pour l’exercice : il illustre une distinction de Durkheim.","documents":[{"id":"visite","type":"texte","genre":"recit","titre":"La visite de Lina","blocs":["Lina visite une mosquée avec sa classe. Devant la porte, elle retire ses chaussures, comme tous les visiteurs. Un peu plus loin, dans la boulangerie voisine, personne ne fait de même : on entre, on achète du pain, on repart."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que le lieu est traité comme sacré.","aide":"Quel objet Lina retire-t-elle devant la porte ?","type":"zone","document":"visite","multiple":false},{"enonce":"Range ces gestes du récit et du quotidien.","aide":"Le sacré est séparé et interdit ; le profane est ordinaire.","type":"categories","categories":[{"id":"c0","texte":"Rapport au sacré"},{"id":"c1","texte":"Rapport au profane"}],"items":[{"id":"i0","texte":"Se taire en entrant dans une synagogue"},{"id":"i1","texte":"Entrer dans un magasin sans y penser"},{"id":"i2","texte":"Acheter du pain à la boulangerie"},{"id":"i3","texte":"Retirer ses chaussures devant une salle de prière"}]},{"enonce":"Associe chaque mot à sa définition.","aide":"Durkheim définit la religion par ces trois idées.","type":"association","gauche":[{"id":"g0","texte":"Le sacré"},{"id":"g1","texte":"Le profane"},{"id":"g2","texte":"Une communauté morale"}],"droite":[{"id":"d0","texte":"Ce qui est ordinaire et de tous les jours"},{"id":"d1","texte":"Ceux qui partagent les mêmes croyances et pratiques"},{"id":"d2","texte":"Ce qui est séparé et interdit"}]}]}$ex$::jsonb,
