  ('38b9181a-0151-595b-97b9-8e9ffe00157a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Foi et raison","competence":"analyser-document","situation":"Quatre élèves parlent de la foi et de la raison. Reconnais la position de chacun, puis examine le pari de Pascal.","documents":[{"id":"eleves","type":"fiche","modele":"affiche","entete":"Quatre élèves","sousTitre":"Phrases écrites pour l’exercice","emoji":"💭","teinte":"violet","lignes":[{"texte":"Eli : « La foi met mon intelligence en route : je crois pour mieux comprendre. »","id":"z1"},{"texte":"Jade : « Si Dieu est l’auteur de la raison et de la foi, elles ne peuvent se contredire. »","id":"z2"},{"texte":"Lou : « Ma raison ne peut ni prouver ni réfuter que Dieu existe : je dois limiter mon savoir. »","id":"z3"},{"texte":"Noa : « Il existe une connaissance du cœur que la raison ne connaît pas. »","id":"z4"}]},{"id":"pari","type":"texte","genre":"source","titre":"Le pari, résumé","blocs":["Si je parie que Dieu existe et que j’ai raison, je gagne tout ; s’il n’existe pas, je ne perds presque rien."],"source":"Résumé du pari de Pascal, écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’élève qui parle comme Thomas d’Aquin.","aide":"Thomas d’Aquin : la foi et la raison viennent toutes deux de Dieu.","type":"zone","document":"eleves","multiple":false},{"enonce":"Touche l’élève qui parle comme Kant.","aide":"Kant limite le savoir pour faire place à la croyance.","type":"zone","document":"eleves","multiple":false},{"enonce":"Quel auteur Noa rappelle-t-il ?","aide":"Pensée sur les raisons du cœur.","type":"choix","options":[{"id":"a","texte":"Durkheim"},{"id":"b","texte":"Marx"},{"id":"c","texte":"Pascal"},{"id":"d","texte":"Freud"}],"multiple":false},{"enonce":"Le pari de Pascal prouve-t-il que Dieu existe ?","aide":"Le pari s’adresse à celui qui doute.","type":"choix","options":[{"id":"a","texte":"Non : il montre seulement qu’il est raisonnable de croire quand on doute"},{"id":"b","texte":"Non : il montre que croire est toujours un choix déraisonnable"},{"id":"c","texte":"Oui : il démontre l’existence de Dieu par un calcul de gains"},{"id":"d","texte":"Oui : il prouve que la raison suffit à régler toute question"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est **Jade** : pour Thomas d’Aquin, la foi et la raison ne peuvent se contredire."},{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est **Lou** : pour Kant, la raison ne peut ni prouver ni réfuter l’existence de Dieu."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est **Pascal** : « le cœur a ses raisons que la raison ne connaît point »."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le pari n’est **pas une preuve** : il s’adresse à celui qui doute et montre qu’il est raisonnable de miser sur la foi."}]$ex$::jsonb),
