  ('6576bad1-a183-535b-b281-9263a9acbbd8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Louis et la machine","competence":"analyser-texte","situation":"Dans ce récit écrit pour l’exercice, un artisan et un ouvrier font le même geste de deux façons.","documents":[{"id":"scie","type":"texte","genre":"recit","titre":"La planche","blocs":["À l’atelier, Louis scie une planche à la main : c’est lui qui guide la scie. À l’usine voisine, une machine scie mille planches par jour, et l’ouvrier suit son rythme en la rechargeant sans cesse."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que l’outil est conduit par l’homme.","aide":"Qui conduit la scie, à l’atelier ?","type":"zone","document":"scie","multiple":false},{"enonce":"Touche le mot qui montre que l’ouvrier dépend du rythme de la machine.","aide":"Qui impose le rythme, à l’usine ?","type":"zone","document":"scie","multiple":false},{"enonce":"Quelle phrase résume la différence entre l’outil et la machine ?","aide":"Regarde qui décide du geste dans chaque cas.","type":"choix","options":[{"id":"a","texte":"L’outil prolonge la main guidée par l’homme, la machine fait le geste à sa place"},{"id":"b","texte":"L’outil est dangereux pour l’homme, la machine est toujours sûre"},{"id":"c","texte":"L’outil est plus récent que la machine et plus efficace qu’elle"},{"id":"d","texte":"La machine est toujours guidée par l’homme, l’outil jamais"}],"multiple":false},{"enonce":"Associe chaque penseur à son idée.","aide":"Faiblesse, outils, usine, ignorance.","type":"association","gauche":[{"id":"g0","texte":"Prométhée"},{"id":"g1","texte":"Bergson"},{"id":"g2","texte":"Marx"},{"id":"g3","texte":"Simondon"}],"droite":[{"id":"d0","texte":"L’ignorance du fonctionnement des objets nous rend esclaves"},{"id":"d1","texte":"À l’usine, l’ouvrier devient l’appendice de la machine"},{"id":"d2","texte":"La technique compense la faiblesse naturelle de l’homme"},{"id":"d3","texte":"L’homme est Homo faber, celui qui fabrique des outils"}]}]}$ex$::jsonb,
