  ('6576bad1-a183-535b-b281-9263a9acbbd8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le téléphone de Clara","competence":"argumenter","situation":"Clara analyse son usage du téléphone : lis le graphique, puis classe ses réactions comme le ferait un philosophe.","documents":[{"id":"usage","type":"graphique","forme":"barres-h","titre":"Temps passé sur le téléphone en une journée","categories":["Messages","Vidéos","GPS","Notifications","Recherches scolaires"],"series":[{"nom":"Minutes","valeurs":[50,80,15,40,25],"teinte":"violet"}],"axeY":{"titre":"Durée","unite":"minutes","min":0,"max":90,"pas":10},"axeX":{"titre":"Usage"},"valeurs":false,"source":"Chiffres inventés pour l’exercice"},{"id":"reactions","type":"fiche","modele":"affiche","entete":"Trois réactions de Clara","sousTitre":"Phrases écrites pour l’exercice","emoji":"📱","teinte":"bleu","lignes":[{"texte":"A. « Mon téléphone n’est qu’un outil : tout dépend de ce que j’en fais. »","id":"z1"},{"texte":"B. « Je ne sais pas comment il choisit mes vidéos, et je les regarde sans fin. »","id":"z2"},{"texte":"C. « Même ma vie finit par ressembler à un flux de contenus disponibles. »","id":"z3"}]}],"questions":[{"enonce":"Touche l’usage qui occupe le plus de temps dans la journée de Clara.","aide":"Cherche la barre la plus longue.","type":"zone","document":"usage","multiple":false},{"enonce":"Combien d’heures Clara passe-t-elle en tout sur son téléphone ?","aide":"Additionne les cinq durées, puis divise par 60.","type":"nombre","unite":"h"},{"enonce":"Touche la réaction qui défend l’idée que la technique n’est qu’un moyen.","aide":"Quelle réaction dit que tout dépend de l’usage ?","type":"zone","document":"reactions","multiple":false},{"enonce":"Touche la réaction qui rappelle Simondon.","aide":"Simondon : l’ignorance du fonctionnement nous rend esclaves.","type":"zone","document":"reactions","multiple":false},{"enonce":"Quelle idée de Jonas peut conclure cette réflexion ?","aide":"La technique dit comment faire, pas s’il faut le faire.","type":"choix","options":[{"id":"a","texte":"La technique suffit à dire ce qu’il est juste de faire"},{"id":"b","texte":"Pouvoir faire quelque chose ne dit pas qu’il faut le faire"},{"id":"c","texte":"Seule la science peut décider de l’usage d’un téléphone"},{"id":"d","texte":"Il faut refuser de se servir de toute technique moderne"}],"multiple":false}]}$ex$::jsonb,
