  ('39bcced6-2a97-518c-8c29-627d952462c2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Erreur ou mensonge ?","competence":"analyser-document","situation":"Sara, Tom et Jules parlent d’un bus. Distingue celui qui se trompe de celui qui ment.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Ce matin","participants":[{"nom":"Sara","emoji":"👧","cote":"gauche"},{"nom":"Jules","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sara","texte":"Le bus passe à 8 h 10, je te le promets !"},{"qui":"Jules","texte":"Il est déjà parti, il passait à 8 h 05."},{"qui":"Sara","texte":"Oh, je me suis trompée, pardon !"},{"qui":"Jules","texte":"Au fait, j’ai dit à Léo que le bus passait à 8 h 30 pour qu’il le rate. Je savais que c’était faux."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot par lequel Sara reconnaît son erreur.","aide":"Quel mot dit que Sara s’est fait avoir par elle-même ?","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces situations : erreur ou mensonge ?","aide":"L’erreur est involontaire ; le mensonge est voulu.","type":"categories","categories":[{"id":"c0","texte":"Erreur"},{"id":"c1","texte":"Mensonge"}],"items":[{"id":"i0","texte":"Dire une heure qu’on sait fausse pour tromper"},{"id":"i1","texte":"Se tromper dans un calcul"},{"id":"i2","texte":"Cacher volontairement ce qu’on sait"},{"id":"i3","texte":"Dire une heure fausse en la croyant exacte"}]},{"enonce":"Pourquoi Jules ment-il alors que Sara se trompe ?","aide":"Regarde ce que chacun savait en parlant.","type":"choix","options":[{"id":"a","texte":"Jules connaît mieux les horaires de bus que Sara"},{"id":"b","texte":"Jules a parlé plus tard que Sara dans la conversation"},{"id":"c","texte":"Jules veut tromper alors qu’il sait que c’est faux"},{"id":"d","texte":"Jules a dit une phrase plus longue que celle de Sara"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25"]},"explication":"C’est **« trompée »** : Sara a dit une chose fausse en la croyant vraie, c’est une erreur."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"L’**erreur** est involontaire, le **mensonge** est une volonté de tromper."},{"cle":{"type":"choix","ids":["c"]},"explication":"Jules **savait** que son information était fausse et voulait **tromper** : c’est un mensonge."}]$ex$::jsonb),
  ('39bcced6-2a97-518c-8c29-627d952462c2'::uuid, 2, 2, 10, 35, 4,
