  ('39bcced6-2a97-518c-8c29-627d952462c2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Doit-on toujours dire la vérité ?","competence":"argumenter","situation":"Un ami est caché chez Hugo et quelqu’un de menaçant demande où il est. Kant et Benjamin Constant n’y répondraient pas pareil.","documents":[{"id":"cas","type":"texte","genre":"recit","titre":"L’ami caché","blocs":["Un soir, Hugo cache son ami Léo chez lui. Un homme menaçant sonne et demande : « Léo est-il ici ? » Hugo hésite : dire la vérité, c’est peut-être mettre Léo en danger."],"source":"Situation écrite pour l’exercice"},{"id":"positions","type":"fiche","modele":"affiche","entete":"Deux positions","sousTitre":"Idées résumées pour l’exercice","emoji":"⚖️","teinte":"bleu","lignes":[{"texte":"Kant : le mensonge ruine la confiance sur laquelle repose toute parole, même face à un assassin.","id":"z1"},{"texte":"Benjamin Constant : on ne doit la vérité qu’à ceux qui y ont droit.","id":"z2"}]}],"questions":[{"enonce":"Touche la position qui refuse tout droit de mentir.","aide":"Laquelle dit qu’on ne peut jamais mentir ?","type":"zone","document":"positions","multiple":false},{"enonce":"Touche la position qui admet une exception pour l’homme menaçant.","aide":"Qui limite la vérité à ceux qui y ont droit ?","type":"zone","document":"positions","multiple":false},{"enonce":"Trie ces arguments pour le sujet « Doit-on toujours dire la vérité ? »","aide":"Deux arguments soutiennent Kant, deux soutiennent Constant.","type":"categories","categories":[{"id":"c0","texte":"Pour dire toujours la vérité"},{"id":"c1","texte":"Pour admettre une exception"}],"items":[{"id":"i0","texte":"Sauver une vie vaut plus que l’exactitude d’une phrase"},{"id":"i1","texte":"L’homme menaçant n’a pas droit à la vérité"},{"id":"i2","texte":"Si on ment, plus personne ne croit personne"},{"id":"i3","texte":"Un menteur ruine la confiance qui rend la parole possible"}]},{"enonce":"Quelle problématique convient au sujet « Doit-on toujours dire la vérité ? »","aide":"Cherche la tension entre deux réponses qui semblent vraies.","type":"choix","options":[{"id":"a","texte":"Les mensonges sont-ils plus fréquents à l’école que dans la famille ?"},{"id":"b","texte":"Pourquoi certains élèves copient-ils leurs devoirs sur leurs voisins ?"},{"id":"c","texte":"La vérité se trouve-t-elle seulement dans les livres de sciences ?"},{"id":"d","texte":"Si la vérité fonde la confiance, peut-elle parfois mettre quelqu’un en danger ?"}],"multiple":false},{"enonce":"Remets dans l’ordre un plan en trois temps.","aide":"Thèse, objection, dépassement.","type":"ordre","items":[{"id":"a","texte":"Dès lors, on peut distinguer mentir pour nuire et protéger quelqu’un"},{"id":"b","texte":"Mais on ne la doit qu’à ceux qui y ont droit"},{"id":"c","texte":"Oui : dire la vérité est la condition de toute confiance"}]}]}$ex$::jsonb,
